/* ===== 设计令牌（浅色·简约清爽科技风·主色健康青绿）===== */
:root{
  --bg-page:#F5F8F7; --bg-section:#EEF4F2; --bg-card:#FFFFFF; --bg-hover:#E8F5F2;
  --text-primary:#16211E; --text-secondary:#4A5A56; --text-tertiary:#8A9995; --text-on-primary:#FFFFFF;
  --color-primary:#0D9488; --color-primary-hover:#0B7D73; --color-primary-light:#E4F5F2;
  --color-accent:#2563EB; --color-success:#059669; --color-warning:#F59E0B; --color-danger:#EF4444;
  --c-carb:#F59E0B; --c-pro:#0D9488; --c-fat:#2563EB;
  --shadow-xs:0 1px 2px rgba(15,40,35,.04);
  --shadow-sm:0 2px 4px rgba(15,40,35,.05),0 1px 2px rgba(15,40,35,.03);
  --shadow-md:0 4px 12px rgba(15,40,35,.07),0 1px 3px rgba(15,40,35,.04);
  --shadow-lg:0 12px 28px rgba(15,40,35,.12),0 4px 8px rgba(15,40,35,.05);
  --radius-sm:6px; --radius:10px; --radius-lg:14px;
  --s1:4px; --s2:8px; --s3:12px; --s4:16px; --s6:24px; --s8:32px;
  --transition:.25s cubic-bezier(.4,0,.2,1);
  --font-family:-apple-system,"Microsoft YaHei","PingFang SC","Segoe UI",sans-serif;
}
*{margin:0;padding:0;box-sizing:border-box}
html,body{font-family:var(--font-family);background:var(--bg-page);color:var(--text-primary);-webkit-font-smoothing:antialiased}
body{padding:0 0 40px}
button{border:none;cursor:pointer;font-family:inherit;background:none}
a{text-decoration:none;color:inherit}

/* ===== 画布：移动端 375px ===== */
.device-mobile{width:375px;min-height:100vh;margin:0 auto;background:var(--bg-page);position:relative;box-shadow:var(--shadow-lg);overflow-x:hidden}

/* ===== 页面容器 ===== */
.page{display:none;min-height:100vh;padding-bottom:72px}
.page.active{display:block;animation:fadeIn .28s ease}
.page.active.overlay-page{display:flex}
@keyframes fadeIn{from{opacity:0;transform:translateX(12px)}to{opacity:1;transform:translateX(0)}}

/* ===== 顶部导航 ===== */
.nav-bar{height:44px;background:var(--bg-card);border-bottom:1px solid #E9EFED;display:flex;align-items:center;padding:0 12px;position:sticky;top:0;z-index:100;box-shadow:var(--shadow-xs)}
.nav-back{font-size:20px;cursor:pointer;color:var(--text-primary);width:32px;transition:transform var(--transition)}
.nav-back:hover{transform:translateX(-3px)}
.nav-title{flex:1;text-align:center;font-size:17px;font-weight:600}
.nav-action{font-size:20px;cursor:pointer;width:32px;text-align:right;color:var(--text-primary)}

/* ===== TabBar ===== */
.tab-bar{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:375px;height:56px;background:var(--bg-card);border-top:1px solid #E9EFED;display:flex;z-index:120;box-shadow:0 -2px 12px rgba(15,40,35,.05)}
.tab-item{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:10px;color:var(--text-tertiary);cursor:pointer;transition:color var(--transition)}
.tab-item:hover{color:var(--text-secondary)}
.tab-item.active{color:var(--color-primary);font-weight:600}
.tab-icon{font-size:20px;margin-bottom:2px}

/* ===== 按钮 ===== */
.btn{height:44px;border-radius:22px;font-size:15px;font-weight:600;display:flex;align-items:center;justify-content:center;transition:all var(--transition)}
.btn:active{transform:scale(.97)}
.btn-primary{background:var(--color-primary);color:#fff;box-shadow:0 2px 6px rgba(13,148,136,.25)}
.btn-primary:hover{background:var(--color-primary-hover);box-shadow:0 6px 14px rgba(13,148,136,.32);transform:translateY(-1px)}
.btn-secondary{background:var(--bg-card);color:var(--color-primary);border:1px solid var(--color-primary)}
.btn-secondary:hover{background:var(--color-primary-light)}
.btn-gray{background:var(--bg-section);color:var(--text-secondary)}
.btn-gray:hover{background:#E2EBE8}
.btn-danger{background:var(--color-danger);color:#fff}
.btn-disabled{background:#DFE6E4;color:var(--text-tertiary);cursor:not-allowed;box-shadow:none}
.btn-block{width:100%}
.btn-sm{height:32px;border-radius:16px;font-size:13px;padding:0 16px}

/* ===== 卡片 ===== */
.card{background:var(--bg-card);border-radius:var(--radius);box-shadow:var(--shadow-sm);margin:12px;padding:14px;transition:all var(--transition)}
.card:hover{box-shadow:var(--shadow-md);transform:translateY(-2px)}
.card-title{font-size:15px;font-weight:600;margin-bottom:8px;display:flex;align-items:center;gap:6px}
.sec-title{font-size:14px;font-weight:600;margin:16px 12px 8px;color:var(--text-secondary);display:flex;align-items:center;gap:6px}
.muted{color:var(--text-tertiary);font-size:12px;line-height:1.6}
.small{font-size:12px;color:var(--text-secondary);line-height:1.7}

/* ===== 标签 ===== */
.tag{display:inline-block;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:500}
.tag-primary{background:var(--color-primary-light);color:var(--color-primary)}
.tag-success{background:#D8F3E7;color:var(--color-success)}
.tag-warning{background:#FEF3C7;color:#92400E}
.tag-danger{background:#FEE2E2;color:var(--color-danger)}
.tag-info{background:#E0EDFF;color:var(--color-accent)}
.fn-tag{display:inline-block;padding:1px 6px;border-radius:4px;font-size:10px;background:#EEF4F2;color:var(--text-tertiary);font-weight:500;margin-left:4px;letter-spacing:.3px}

/* ===== 列表 ===== */
.list-item{display:flex;align-items:center;padding:12px;border-bottom:1px solid #EEF2F1;cursor:pointer;transition:background var(--transition);gap:10px}
.list-item:hover{background:var(--bg-hover)}
.list-item:last-child{border-bottom:none}
.li-main{flex:1;min-width:0}
.li-title{font-size:14px;font-weight:500}
.li-sub{font-size:12px;color:var(--text-tertiary);margin-top:2px}
.li-arrow{color:var(--text-tertiary);font-size:16px}

/* ===== 表单 ===== */
.form-group{margin-bottom:14px}
.form-group label{display:block;font-size:13px;color:var(--text-secondary);margin-bottom:6px;font-weight:500}
.form-input,.form-select{width:100%;height:44px;padding:0 12px;border:1px solid #DDE6E3;border-radius:var(--radius-sm);font-size:14px;background:var(--bg-card);transition:all var(--transition);color:var(--text-primary);font-family:inherit}
.form-input:focus,.form-select:focus{outline:none;border-color:var(--color-primary);box-shadow:0 0 0 3px rgba(13,148,136,.12)}
.form-input.err{border-color:var(--color-danger);box-shadow:0 0 0 3px rgba(239,68,68,.1)}
.form-err{font-size:12px;color:var(--color-danger);margin-top:4px;display:none}
.form-hint{font-size:11px;color:var(--text-tertiary);margin-top:4px}

/* ===== 分段选择 ===== */
.seg{display:flex;gap:8px;flex-wrap:wrap}
.seg-item{flex:1;min-width:70px;text-align:center;padding:9px 6px;border-radius:var(--radius-sm);background:var(--bg-section);font-size:13px;color:var(--text-secondary);cursor:pointer;transition:all var(--transition);border:1px solid transparent}
.seg-item:hover{background:#E2EBE8}
.seg-item.active{background:var(--color-primary-light);color:var(--color-primary);border-color:var(--color-primary);font-weight:600}

/* ===== 宏量进度条 ===== */
.macro-row{margin-bottom:12px}
.macro-head{display:flex;justify-content:space-between;align-items:baseline;font-size:12px;margin-bottom:5px}
.macro-name{font-weight:600}
.macro-name i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:5px}
.macro-val{color:var(--text-secondary)}
.macro-val b{color:var(--text-primary);font-size:13px}
.macro-val .over{color:var(--color-danger);font-weight:700}
.macro-bar{height:8px;border-radius:4px;background:var(--bg-section);overflow:hidden}
.macro-bar>i{display:block;height:100%;border-radius:4px;transition:width .45s cubic-bezier(.4,0,.2,1)}

/* ===== KPI ===== */
.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
.kpi{background:var(--bg-section);border-radius:var(--radius-sm);padding:10px 6px;text-align:center}
.kpi b{display:block;font-size:16px;line-height:1.3}
.kpi span{font-size:11px;color:var(--text-tertiary)}
.kpi.white{background:var(--bg-card);border:1px solid #E9EFED}

/* ===== 周期日卡片 ===== */
.day-card{display:flex;align-items:center;gap:10px;background:var(--bg-card);border:1px solid #E9EFED;border-radius:var(--radius);padding:10px 12px;margin-bottom:8px;transition:all var(--transition)}
.day-card:hover{box-shadow:var(--shadow-sm);transform:translateX(2px)}
.day-badge{width:44px;height:44px;border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-size:11px;font-weight:700;flex-shrink:0}
.day-badge b{font-size:15px;line-height:1}
.day-info{flex:1;min-width:0}
.day-info .d1{font-size:14px;font-weight:600}
.day-info .d2{font-size:11px;color:var(--text-tertiary);margin-top:2px}
.day-kcal{font-size:13px;font-weight:700;text-align:right;flex-shrink:0}
.day-kcal span{display:block;font-size:10px;color:var(--text-tertiary);font-weight:400}

/* ===== 阶段卡 ===== */
.phase-card{background:var(--bg-card);border-radius:var(--radius);box-shadow:var(--shadow-sm);padding:12px;margin-bottom:10px;border-left:4px solid var(--color-primary);transition:all var(--transition)}
.phase-card:hover{box-shadow:var(--shadow-md);transform:translateY(-2px)}
.phase-card.done{border-left-color:#D5E0DD}
.phase-card.current{border-left-color:var(--color-primary);background:linear-gradient(180deg,#F3FBF9 0%,#FFFFFF 60%)}
.phase-card.future{border-left-color:#E2EBE8}
.phase-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}
.phase-name{font-size:14px;font-weight:600}
.phase-desc{font-size:12px;color:var(--text-secondary);line-height:1.6;margin-bottom:8px}

/* ===== 食物项 ===== */
.food-item{display:flex;align-items:center;gap:10px;padding:11px 12px;border-bottom:1px solid #EEF2F1;cursor:pointer;transition:background var(--transition)}
.food-item:hover{background:var(--bg-hover)}
.food-emoji{width:36px;height:36px;border-radius:9px;background:var(--bg-section);display:flex;align-items:center;justify-content:center;font-size:19px;flex-shrink:0}
.food-main{flex:1;min-width:0}
.food-name{font-size:14px;font-weight:500}
.food-meta{font-size:11px;color:var(--text-tertiary);margin-top:2px}
.food-kcal{font-size:13px;font-weight:600;color:var(--text-secondary);flex-shrink:0}
.food-kcal span{font-size:10px;color:var(--text-tertiary);font-weight:400}

/* ===== 记录项 ===== */
.rec-item{display:flex;gap:10px;padding:11px 12px;border-bottom:1px solid #EEF2F1;align-items:flex-start}
.rec-meal{width:44px;flex-shrink:0}
.rec-meal .m{font-size:12px;font-weight:700;color:var(--color-primary)}
.rec-meal .t{font-size:10px;color:var(--text-tertiary)}
.rec-main{flex:1;min-width:0}
.rec-name{font-size:14px;font-weight:500}
.rec-macro{font-size:11px;color:var(--text-tertiary);margin-top:3px}
.rec-macro em{font-style:normal;margin-right:8px}
.rec-del{color:var(--text-tertiary);font-size:15px;cursor:pointer;padding:2px 4px;border-radius:4px;transition:all var(--transition);flex-shrink:0}
.rec-del:hover{color:var(--color-danger);background:#FEE2E2}

/* ===== 开关 ===== */
.switch{width:46px;height:26px;border-radius:13px;background:#D8E2DF;position:relative;transition:background var(--transition);flex-shrink:0;cursor:pointer}
.switch.on{background:var(--color-primary)}
.switch::after{content:'';position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.15);transition:transform var(--transition)}
.switch.on::after{transform:translateX(20px)}

/* ===== 步进器 ===== */
.stepper{display:flex;align-items:center;gap:12px;justify-content:center;margin:8px 0}
.step-btn{width:34px;height:34px;border-radius:50%;background:var(--bg-section);font-size:18px;color:var(--text-secondary);display:flex;align-items:center;justify-content:center;transition:all var(--transition)}
.step-btn:hover{background:var(--color-primary-light);color:var(--color-primary)}
.step-val{font-size:22px;font-weight:700;min-width:78px;text-align:center}

/* ===== 骨架屏 / 空 / 错误 ===== */
.state-container{animation:fadeIn .25s ease}
.skeleton{background:linear-gradient(90deg,#EEF4F2 25%,#F7FBFA 37%,#EEF4F2 63%);background-size:400% 100%;animation:shimmer 1.3s ease infinite;border-radius:var(--radius-sm)}
@keyframes shimmer{0%{background-position:100% 50%}100%{background-position:0 50%}}
.sk-line{height:14px;margin-bottom:10px}
.sk-block{height:88px;margin-bottom:12px}
.state-empty{text-align:center;padding:56px 32px;color:var(--text-tertiary)}
.state-empty .empty-icon{font-size:54px;margin-bottom:14px;opacity:.85}
.state-empty .empty-text{font-size:14px;margin-bottom:6px;color:var(--text-secondary)}
.state-empty .empty-sub{font-size:12px;margin-bottom:18px}
.state-error{text-align:center;padding:56px 32px}
.state-error .err-icon{font-size:54px;margin-bottom:14px}
.state-error .err-text{font-size:14px;color:var(--text-secondary);margin-bottom:6px}
.state-error .err-sub{font-size:12px;color:var(--text-tertiary);margin-bottom:18px}

/* ===== 状态切换器 ===== */
.switcher-bar{display:flex;align-items:center;gap:6px;padding:8px 12px;background:#FFF9EC;border-bottom:1px solid #F3E7CC}
.switcher-bar .sl{font-size:11px;color:#92700F;font-weight:600;flex-shrink:0}
.state-switcher{display:inline-flex;gap:3px;background:#F5EEDF;padding:3px;border-radius:7px}
.state-btn{padding:3px 9px;border-radius:5px;font-size:11px;background:transparent;color:#8A7A55;transition:all var(--transition);font-weight:500}
.state-btn.active{background:var(--color-primary);color:#fff;box-shadow:0 1px 3px rgba(13,148,136,.3)}
.state-btn:hover:not(.active){background:#EAE1CE}

/* ===== 弹窗 ===== */
.modal-overlay{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(12,32,28,.5);z-index:900;display:none;align-items:center;justify-content:center}
.modal-overlay.show{display:flex}
.modal{background:var(--bg-card);border-radius:var(--radius-lg);width:311px;max-width:88vw;padding:20px;box-shadow:var(--shadow-lg);animation:modalIn .3s cubic-bezier(.34,1.4,.64,1)}
@keyframes modalIn{from{opacity:0;transform:scale(.9) translateY(10px)}to{opacity:1;transform:scale(1) translateY(0)}}
.modal-title{font-size:17px;font-weight:600;margin-bottom:10px;text-align:center}
.modal-body{font-size:13px;color:var(--text-secondary);margin-bottom:18px;line-height:1.7}
.modal-footer{display:flex;gap:10px}
.modal-footer .btn{flex:1;height:40px;font-size:14px}

/* ===== 全屏遮罩页（P15/P16）===== */
.overlay-page{position:absolute;top:0;left:0;width:375px;min-height:100vh;background:rgba(12,32,28,.62);z-index:200;align-items:center;justify-content:center;padding:24px}
.op-card{background:var(--bg-card);border-radius:16px;padding:22px 18px;width:100%;box-shadow:var(--shadow-lg);animation:modalIn .32s cubic-bezier(.34,1.4,.64,1)}
.op-icon{font-size:44px;text-align:center;margin-bottom:10px}
.op-title{font-size:18px;font-weight:700;text-align:center;margin-bottom:10px}
.op-desc{font-size:13px;color:var(--text-secondary);line-height:1.75;margin-bottom:14px;text-align:center}
.op-box{background:var(--bg-section);border-radius:var(--radius);padding:10px 12px;margin-bottom:16px;font-size:12px;color:var(--text-secondary);line-height:1.7}

/* ===== Toast ===== */
.toast{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(16,38,34,.9);color:#fff;padding:12px 22px;border-radius:10px;font-size:14px;z-index:9999;display:none;box-shadow:var(--shadow-lg);max-width:78vw;text-align:center;line-height:1.6}
.toast.show{display:block;animation:toastIn .28s ease}
@keyframes toastIn{from{opacity:0;transform:translate(-50%,-46%)}to{opacity:1;transform:translate(-50%,-50%)}}

/* ===== 浮动工具按钮 ===== */
.float-btn{position:fixed;z-index:950;background:var(--color-primary);color:#fff;padding:8px 14px;border-radius:20px;font-size:13px;font-weight:600;box-shadow:0 4px 14px rgba(13,148,136,.3);transition:all var(--transition)}
.float-btn:hover{background:var(--color-primary-hover);transform:translateY(-2px);box-shadow:0 6px 18px rgba(13,148,136,.38)}
#btn-index{top:16px;left:16px}
#btn-walk{top:16px;right:16px}

/* ===== 侧边面板（目录 / 走查）===== */
.side-panel{position:fixed;top:0;width:560px;max-width:92vw;height:100vh;overflow-y:auto;background:var(--bg-card);z-index:940;box-shadow:-6px 0 28px rgba(12,32,28,.16);transition:transform .32s cubic-bezier(.4,0,.2,1)}
#panel-index{left:0;transform:translateX(-100%);box-shadow:6px 0 28px rgba(12,32,28,.16)}
#panel-index.show{transform:translateX(0)}
#panel-walk{right:0;transform:translateX(100%)}
#panel-walk.show{transform:translateX(0)}
.panel-inner{padding:20px 22px 40px}
.panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;padding-bottom:12px;border-bottom:2px solid var(--bg-section)}
.panel-head h3{font-size:17px}
.panel-close{cursor:pointer;font-size:20px;color:var(--text-tertiary);transition:color var(--transition)}
.panel-close:hover{color:var(--text-primary)}
.panel-meta{font-size:12px;color:var(--text-tertiary);margin-bottom:14px;line-height:1.7}
.panel-tabs{display:flex;gap:6px;margin-bottom:14px;background:var(--bg-section);padding:4px;border-radius:9px}
.panel-tab{flex:1;text-align:center;padding:7px;font-size:13px;border-radius:6px;color:var(--text-secondary);cursor:pointer;transition:all var(--transition);font-weight:500}
.panel-tab.active{background:var(--bg-card);color:var(--color-primary);font-weight:700;box-shadow:var(--shadow-xs)}
.wt{width:100%;border-collapse:collapse;font-size:12px;margin-bottom:8px}
.wt th{background:var(--color-primary);color:#fff;padding:8px 6px;text-align:left;font-weight:600;font-size:11px}
.wt td{padding:7px 6px;border-bottom:1px solid #EEF2F1;vertical-align:top;line-height:1.6}
.wt tr:hover td{background:var(--bg-hover)}
.wt .step-n{font-weight:700;color:var(--color-primary);text-align:center}
.idx-group{margin-bottom:14px}
.idx-group h4{font-size:13px;color:var(--text-secondary);margin-bottom:7px;padding-left:8px;border-left:3px solid var(--color-primary)}
.idx-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}
.idx-item{padding:8px 10px;border-radius:var(--radius-sm);background:var(--bg-section);font-size:12px;cursor:pointer;transition:all var(--transition);display:flex;gap:6px;align-items:center}
.idx-item:hover{background:var(--color-primary-light);color:var(--color-primary);transform:translateX(2px)}
.idx-item b{color:var(--color-primary);font-size:11px}
.idx-item.cur{background:var(--color-primary);color:#fff}
.idx-item.cur b{color:#fff}
.ia-tree{font-size:12px;line-height:2;background:var(--bg-section);border-radius:var(--radius);padding:12px 14px;margin-bottom:14px}
.ia-tree .lv1{font-weight:700;color:var(--color-primary);margin-top:6px}
.ia-tree .lv2{padding-left:18px;color:var(--text-secondary)}
.ia-tree .lv3{padding-left:36px;color:var(--text-tertiary)}
.report-box{background:#F3FBF9;border:1px solid #C9E9E3;border-radius:var(--radius);padding:12px;margin-bottom:12px}
.report-box h4{font-size:13px;margin-bottom:8px;color:var(--color-primary)}
.ok{color:var(--color-success);font-weight:700}
.warn-t{color:var(--color-warning);font-weight:700}

/* ===== 免责声明 ===== */
.disclaimer{background:#FFF8E8;border:1px solid #F5E6C0;border-radius:var(--radius);padding:10px 12px;font-size:11px;color:#8A6D14;line-height:1.7;margin:0 12px 12px}
.demo-note{background:#EEF4FF;border:1px dashed #B9CFEA;border-radius:var(--radius-sm);padding:8px 10px;font-size:11px;color:#4A6FA5;line-height:1.7;margin:0 12px 12px}

