/* ================= 状态数据 ================= */
var S = {
  gender:'female', age:30, height:162, weight:55,
  targetWeight:53,    // 🆕 目标体重（碳循环模式：碳水 / 脂肪池的核算基数）
  act:1.375, actLabel:'轻度活动（每周1-3次）',
  mode:'532',
  cycleDays:7,
  train:[],          // true=运动日
  period:false,
  deficit:200,
