/* ================= 计算逻辑（对齐 PRD §IV §V 口径） ================= */
/* P01 BMR/Mifflin-St Jeor; P01 TDEE/活动系数 */
function bmr(){
  var base = 10*S.weight + 6.25*S.height - 5*S.age;
  return S.gender==='male' ? base + 5 : base - 161;
}
function tdee(){ return bmr() * S.act; }
function targetKcal(){ return tdee() - S.deficit; }   // ★ 532 与 碳循环的共同基准 = TDEE − X

/* 532 模式：按目标热量 50/30/20 切 */
function macro532(){
  var total = targetKcal();
  var c = total*0.5/4, p = total*0.3/4, f = total*0.2/9;
  if(S.period){ c += 15; total += 60; }   // 经期阶段2 碳水+15g、总热量+60kcal
  return {kcal:Math.round(total), c:Math.round(c), p:Math.round(p), f:Math.round(f)};
}

/* 碳循环常量（PRD §IV 图片公式）：
 *   7天总碳水  = 目标体重 × 2.5 × cycleDays
 *   7天总脂肪  = 目标体重 × 脂肪系数 × cycleDays        系数默认 0.8，可调 1.0（更易执行）
 *   每日蛋白质 = 当前体重 × 1.5                          （周期内每口都是这个值，固定量）
 */
function carbonConst(){
  var tw = S.targetWeight || S.weight;
  var cfc = S.carbFatCoef || 0.8;
  var pool = tw * 2.5 * S.cycleDays;      // 7天碳水池
  var poolFat = tw * cfc * S.cycleDays;   // 7天脂肪池
  var pro = S.weight * 1.5;               // 每日蛋白（当前体重 × 1.5，固定）
  return {tw:tw, cfc:cfc, pool:pool, poolFat:poolFat, pro:pro};
}

/* 碳循环每日分配（PRD §IV 图片公式）：
 *   高碳日：碳水 = 总碳水 × 50% ÷ 2    脂肪 = 总脂肪 × 15% ÷ 2
 *   中碳日：碳水 = 总碳水 × 35% ÷ 2.2  脂肪 = 总脂肪 × 35% ÷ 2.2
 *   低碳日：碳水 = 总碳水 × 15% ÷ 2    脂肪 = 总脂肪 × 50% ÷ 2
 * 2/2.2/2 是周内对应类型的天数；周期长度按比例放大。
 */
function cycleAlloc(){
  var cc = carbonConst();
  var N = S.cycleDays;
  var w = N / 7;                          // 周倍数（7 天→1；14 天→2）
  var nH = 2 * w, nM = 2.2 * w, nL = 2 * w;
  var perH_carb = cc.pool * 0.5  / nH, perH_fat = cc.poolFat * 0.15 / nH;
  var perM_carb = cc.pool * 0.35 / nM, perM_fat = cc.poolFat * 0.35 / nM;
  var perL_carb = cc.pool * 0.15 / nL, perL_fat = cc.poolFat * 0.5  / nL;
  // 周期日序模板：高 / 中 / 低 / 低 / 中 / 高 / 低
  var base = ['高','中','低','低','中','高','低'];
  var order = [];
  for(var i=0;i<N;i++) order.push(base[i%7]);
  // 运动日智能适配：运动日优先占高碳位，其次中碳位
  for(var a=0;a<N;a++){
    if(S.train[a] && order[a] !== '高'){
      for(var b=0;b<N;b++){
        if(!S.train[b] && order[b] === '高'){ var t=order[a]; order[a]=order[b]; order[b]=t; break; }
      }
    }
  }
  for(var a2=0;a2<N;a2++){
    if(S.train[a2] && order[a2] === '低'){
      for(var b2=0;b2<N;b2++){
        if(!S.train[b2] && order[b2] === '中'){ var t2=order[a2]; order[a2]=order[b2]; order[b2]=t2; break; }
      }
    }
  }
  return {
    order:order, cc:cc, nH:nH, nM:nM, nL:nL,
    perH_carb:perH_carb, perH_fat:perH_fat,
    perM_carb:perM_carb, perM_fat:perM_fat,
    perL_carb:perL_carb, perL_fat:perL_fat,
    pro:cc.pro
  };
}

