function recalc(){
  var age = parseFloat(el('in-age').value);
  var h = parseFloat(el('in-height').value);
  var w = parseFloat(el('in-weight').value);
  var tw = parseFloat(el('in-target-weight').value);
  var ok = true;
  ok = checkRange('in-age','err-age',age,12,80) && ok;
  ok = checkRange('in-height','err-height',h,100,250) && ok;
  ok = checkRange('in-weight','err-weight',w,25,200) && ok;
  ok = checkRange('in-target-weight','err-target-weight',tw,25,200) && ok;
  if(ok && tw > w + 0.1){
    el('err-target-weight').textContent = '目标体重不应大于当前体重（减脂场景）';
    el('in-target-weight').classList.add('err'); ok = false;
  } else {
    el('err-target-weight').textContent = '目标体重需在 25–200kg 之间';
  }
  if(ok){ S.age=age; S.height=h; S.weight=w; S.targetWeight=tw; }
  var b = bmr(), t = tdee();
  el('pre-bmr').textContent = fmt(b);
  el('pre-tdee').textContent = fmt(t);
  el('pre-target').textContent = fmt(targetKcal());
  el('pre-act').textContent = S.act;
  if(el('pre-def')) el('pre-def').textContent = fmt(S.deficit);
  if(el('pre-tw')) el('pre-tw').textContent = fmt(tw);
  TARGET = macro532();
}
function checkRange(inId, errId, v, min, max){
  var bad = !(v>=min && v<=max);
  el(inId).classList.toggle('err', bad);
  el(errId).style.display = bad ? 'block' : 'none';
  return !bad;
}

