  el('dy-p').textContent = fmt(s.p) + 'g';
  el('dy-f').textContent = fmt(s.f) + 'g';
  el('dy-k').textContent = fmt(s.k);
  el('dy-count').textContent = RECORDS.length;
  var over = [];
  if(s.c > TARGET.c) over.push('碳水超 ' + fmt(s.c-TARGET.c) + 'g');
  if(s.p > TARGET.p) over.push('蛋白超 ' + fmt(s.p-TARGET.p) + 'g');
  if(s.f > TARGET.f) over.push('脂肪超 ' + fmt(s.f-TARGET.f) + 'g');
  if(s.k > TARGET.kcal) over.push('总热量超 ' + fmt(s.k-TARGET.kcal) + ' kcal');
  if(over.length){
    el('dy-over').style.display = 'block';
    el('dy-over-text').textContent = over.join('，');
  } else {
    el('dy-over').style.display = 'none';
  }
  var html = '';
  RECORDS.forEach(function(r,i){
    html += '<div class="rec-item"><div class="rec-meal"><div class="m">'+r.meal+'</div><div class="t">'+r.time+'</div></div>'
         +  '<div class="rec-main"><div class="rec-name">'+esc(r.name)+'</div>'
         +  '<div class="rec-macro">'+esc(r.qty)+' · <em style="color:var(--c-carb)">碳 '+r.c+'g</em><em style="color:var(--c-pro)">蛋 '+r.p+'g</em><em style="color:var(--c-fat)">脂 '+r.f+'g</em>'+r.k+' kcal</div></div>'
         +  '<div class="rec-del" onclick="delRecord('+i+')">🗑</div></div>';
  });
  el('dy-list').innerHTML = html;
  renderHome();
}
function renderHome(){
  var s = sumRecords();
  var m = macro532();
  TARGET = {c:m.c,p:m.p,f:m.f,kcal:m.kcal};
  el('home-target').innerHTML = TARGET.kcal + ' <span style="font-size:14px;font-weight:500">kcal</span>';
  var left = TARGET.kcal - s.k;
  el('home-eaten').textContent = fmt(s.k) + ' / ' + (left>=0?fmt(left):'+'+fmt(-left));
  el('home-kcal-bar').style.width = Math.min(100, Math.round(s.k/TARGET.kcal*100)) + '%';
  el('home-kcal-bar').style.background = s.k > TARGET.kcal ? '#FFD5D5' : '#fff';
  [['carb',s.c,TARGET.c],['pro',s.p,TARGET.p],['fat',s.f,TARGET.f]].forEach(function(x){
    var pct = Math.round(x[1]/x[2]*100);
    var over = x[1] > x[2];
    el('mv-'+x[0]).innerHTML = '<b'+(over?' class="over"':'')+'>'+fmt(x[1])+'</b> / '+x[2]+'g' + (over ? ' <span class="over">⚠ 超'+fmt(x[1]-x[2])+'g</span>' : ' · '+pct+'%');
    el('mb-'+x[0]).style.width = Math.min(100,pct) + '%';
    el('mb-'+x[0]).style.background = over ? 'var(--color-danger)' : (x[0]==='carb'?'var(--c-carb)':x[0]==='pro'?'var(--c-pro)':'var(--c-fat)');
  });
  var mc = ['早餐','午餐','晚餐','加餐'];
  var mh = '';
  mc.forEach(function(mm){
    var rs = RECORDS.filter(function(r){ return r.meal===mm; });
    if(rs.length === 0){
      mh += '<div class="rec-item"><div class="rec-meal"><div class="m" style="color:var(--text-tertiary)">'+mm+'</div></div>'
         +  '<div class="rec-main"><div class="rec-name" style="color:var(--text-tertiary);font-weight:400">未记录</div></div>'
         +  '<button class="btn btn-sm btn-gray" style="height:28px;font-size:12px" onclick="showPage(\'page-food\')">＋ 记一餐</button></div>';
    } else {
      rs.forEach(function(r){
        mh += '<div class="rec-item"><div class="rec-meal"><div class="m">'+r.meal+'</div><div class="t">'+r.time+'</div></div>'
           +  '<div class="rec-main"><div class="rec-name">'+esc(r.name)+'</div>'
           +  '<div class="rec-macro"><em style="color:var(--c-carb)">碳 '+r.c+'g</em><em style="color:var(--c-pro)">蛋 '+r.p+'g</em><em style="color:var(--c-fat)">脂 '+r.f+'g</em>'+r.k+' kcal</div></div></div>';
      });
    }
  });
  el('home-meals').innerHTML = mh;
  el('home-mode-tag').textContent = '当前模式：532 碳水渐降 · 阶段1 月初适应期' + (S.period ? ' · 经期适配中' : '');
  updateOverCard(s);
}
function updateOverCard(s){
  var items = [];
  if(s.c > TARGET.c) items.push({k:'碳水', v:'+' + fmt(s.c-TARGET.c) + 'g', u:'g'});
  if(s.p > TARGET.p) items.push({k:'蛋白质', v:'+' + fmt(s.p-TARGET.p) + 'g', u:'g'});
  if(s.f > TARGET.f) items.push({k:'脂肪', v:'+' + fmt(s.f-TARGET.f) + 'g', u:'g'});
  if(s.k > TARGET.kcal) items.push({k:'总热量', v:'+' + fmt(s.k-TARGET.kcal), u:' kcal'});
  if(items.length === 0){ el('over-card').style.display = 'none'; return; }
  el('over-card').style.display = 'block';
  var chips = '';
  items.forEach(function(it){
    chips += '<div style="flex:1;background:#FEE2E2;border-radius:var(--radius-sm);padding:8px 4px;text-align:center">'
          +  '<div style="font-size:16px;font-weight:800;color:var(--color-danger)">' + it.v + '</div>'
          +  '<div style="font-size:11px;color:#B45252">' + it.k + '超标</div></div>';
  });
  el('ov-chips').innerHTML = chips;

  // 小白友好型微调建议（按超标项动态生成）
  var adv = ['<b style="color:var(--text-primary)">🥗 小白友好微调建议</b>'];
  if(s.f > TARGET.f){
    adv.push('脂肪已超 ' + fmt(s.f-TARGET.f) + 'g：下一餐换成清蒸 / 水煮做法，去掉肥肉和油碟，用鸡胸肉、虾仁或嫩豆腐替代肥牛，可回补约 ' + fmt(s.f-TARGET.f) + 'g 脂肪额度。');
  }
  if(s.c > TARGET.c){
    adv.push('碳水已超 ' + fmt(s.c-TARGET.c) + 'g：主食减半或换成糙米 / 红薯，先吃菜和肉再吃饭，饱腹感更强。');
  }
  if(s.p > TARGET.p){
    adv.push('蛋白质略超 ' + fmt(s.p-TARGET.p) + 'g：问题不大，蛋白是保肌关键，只需把脂肪和碳水压回来即可。');
  }
  if(s.k > TARGET.kcal){
    adv.push('总热量超 ' + fmt(s.k-TARGET.kcal) + ' kcal：饭后散步 20–30 分钟即可抵消，<b>不要跳过下一餐</b>，避免暴食反弹。');
  }
  adv.push('<span style="color:var(--text-tertiary)">注：建议为通用饮食调整方向，非医疗建议。</span>');
  el('ov-advice').innerHTML = adv.join('<br>');
}

/* ================= 交互 ================= */
function showPage(id){
  if(!id) return;
  var pages = document.querySelectorAll('.page');
  for(var i=0;i<pages.length;i++) pages[i].classList.remove('active');
  var p = el(id);
  if(p) p.classList.add('active');
  var tabs = document.querySelectorAll('.tab-item');
  for(var j=0;j<tabs.length;j++) tabs[j].classList.toggle('active', tabs[j].getAttribute('data-tab') === id);
  el('tab-bar').style.display = ['page-home','page-diary','page-cycle-plan','page-mine'].indexOf(id) >= 0 ? 'flex' : 'none';
  window.scrollTo(0,0);
  var items = document.querySelectorAll('.idx-item');
  for(var k=0;k<items.length;k++) items[k].classList.toggle('cur', items[k].getAttribute('data-go') === id);
  if(id==='page-home') renderHome();
  if(id==='page-meta') renderMeta();
  if(id==='page-cycle-set') renderCycleSet();
  if(id==='page-cycle-plan') renderCyclePlan();
  if(id==='page-532') render532();
  if(id==='page-food') renderFood();
  if(id==='page-add') renderAdd();
  if(id==='page-diary') renderRecords();
}
function switchState(btn, state){
  var page = btn.closest('.page');
  var cs = page.querySelectorAll('.state-container');
  for(var i=0;i<cs.length;i++) cs[i].style.display = (cs[i].getAttribute('data-state') === state) ? 'block' : 'none';
  var bs = page.querySelectorAll('.state-btn');
  for(var j=0;j<bs.length;j++) bs[j].classList.remove('active');
  btn.classList.add('active');
}
function toast(msg){
  var t = el('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(function(){ t.classList.remove('show'); }, 2000);
}
function openModal(title, body, okText, okFn){
  el('modal-title').textContent = title;
  el('modal-body').innerHTML = body;
  var ok = el('modal-ok');
  ok.textContent = okText || '确认';
  ok.onclick = function(){ closeModal(); if(okFn) okFn(); };
  el('modal-overlay').classList.add('show');
}
function closeModal(){ el('modal-overlay').classList.remove('show'); }

